<script setup>
import {languageDirection} from '../../lib/text-direction.js';
import {ref,watch} from 'vue';import {Head,Link,useForm} from '@inertiajs/vue3';import AppLayout from '../../Layouts/AppLayout.vue';import Errors from '../../Components/Errors.vue';import {useI18n} from '../../lib/i18n.js';import {useDialogEscape} from '../../lib/dialog.js';
defineProps({pools:{type:Array,default:()=>[]}});const {t}=useI18n(),poolOpen=ref(false),poolForm=useForm({name:'',language:'',text_direction:'ltr'});
function openPool(){directionChosen.value=false;poolForm.reset();poolForm.clearErrors();poolOpen.value=true;}
const directionChosen=ref(false);
watch(()=>poolForm.language,language=>{poolForm.text_direction=languageDirection(language,poolForm.text_direction,directionChosen.value);},{flush:'sync'});
function savePool(){if(poolForm.processing)return;poolForm.post('/word-pools',{onSuccess:()=>{poolOpen.value=false;}});}
useDialogEscape(()=>{poolOpen.value=false;});
</script><template><Head :title="t('Word pools')"/><AppLayout :title="t('Word pools')" :subtitle="t('Choose a language pool to explore your words.')"><template #actions><button class="button" @click="openPool">{{t('New word pool')}}</button></template><div v-if="pools.length" class="pool-grid"><Link v-for="(pool,index) in pools" :key="pool.id" :href="`/word-pools/${pool.id}`" class="pool-card" :class="`pool-tone-${index%3}`"><span class="pool-language">{{pool.language}}</span><h2>{{pool.name}}</h2><div class="pool-card-footer"><span>{{t('{count} words',{count:pool.words_count??0})}}</span><span>{{t('Open →')}}</span></div></Link></div><section v-else class="panel empty"><h2>{{t('Create your first word pool')}}</h2><p>{{t('Create a named language pool to add or import words. Existing words are not deleted.')}}</p><button class="button" @click="openPool">{{t('New word pool')}}</button></section>
        <div v-if="poolOpen" class="modal-backdrop" @click.self="poolOpen=false"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="pool-title"><h2 id="pool-title">{{t('New word pool')}}</h2><form @submit.prevent="savePool"><Errors :errors="poolForm.errors"/><label>{{t('Pool name')}}<input v-model="poolForm.name" required maxlength="150"/></label><label>{{t('Language code')}}<input v-model="poolForm.language" list="pool-languages" required maxlength="35" placeholder="en-US, pt-PT, tr"/></label><label>{{t('Text direction')}}<select v-model="poolForm.text_direction" @change="directionChosen=true"><option value="ltr">{{t('Left to right (LTR)')}}</option><option value="rtl">{{t('Right to left (RTL)')}}</option></select></label><datalist id="pool-languages"><option value="ar">العربية</option><option value="he">עברית</option><option value="fa">فارسی</option><option value="ur">اردو</option><option value="en-US">English (US)</option><option value="en-GB">English (UK)</option><option value="pt-PT">Português</option><option value="tr">Türkçe</option><option value="de">Deutsch</option><option value="es">Español</option><option value="fr">Français</option></datalist><p class="muted small">{{t('Use a language code such as en-US or pt-PT. Words keep their original spelling and definition.')}}</p><div class="form-actions"><button type="button" class="button secondary" @click="poolOpen=false">{{t('Cancel')}}</button><button class="button" :disabled="poolForm.processing">{{t('Save pool')}}</button></div></form></section></div>
</AppLayout></template><style scoped>.pool-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,270px),1fr));gap:20px}.pool-card{display:flex;flex-direction:column;min-height:180px;border:1px solid #cde0d6;border-radius:16px;padding:24px;color:#164b3c;text-decoration:none;background:#e9f7ef;overflow-wrap:anywhere}.pool-tone-1{background:#edf3ff;border-color:#c3d5f3;color:#204779}.pool-tone-2{background:#f3edff;border-color:#d7c7ef;color:#573778}.pool-card:focus-visible{outline:3px solid var(--teal,#157e73);outline-offset:3px}.pool-language{font-size:.8rem;font-weight:650}.pool-card h2{font-size:1.4rem;margin:14px 0 24px}.pool-card-footer{display:flex;justify-content:space-between;gap:12px;margin-top:auto}@media(max-width:600px){.pool-grid{grid-template-columns:1fr}.pool-card{min-height:165px;padding:20px}.form-actions{flex-direction:column;align-items:stretch}.form-actions .button{min-height:46px}}</style>